    expect(markdown).toContain('#### 대표 사이트 기반 Layer 2·Layer 3 판정 우선순위');
    expect(markdown).toContain('| 중대한 결정·권리 영향 | 정부24 확정일자 신청, 홈택스 현금영수증 발급, 대한민국법원 상속포기 신고 | 효력·기한·되돌릴 수 없는 결과·대안 절차가 세 서비스에서 같은 구조로 필요한가? | Layer 2 CASE 52 / 3장 core-info / 4장 safety-net / 7장 컴포넌트 |');
    expect(markdown).toContain('| 기관 전용 문화·관람 과업 | SeMA 도슨트 예약, 오프닝 리셉션 신청, 소장품 검색 | 다른 대표 사이트로 옮기면 과업 이름·대상·톤이 그대로 유지되지 않는가? | Layer 3 기관별 추가 사전 / 톤·매너 / 에러 시나리오 |');
    expect(markdown).toContain('#### 순회 판정 로그 한 행 예시');
    expect(markdown).toContain('| 민원 유형 선택 / 휴업·폐업 신고 / 개인회생·파산 | 국민신문고 / 홈택스 / 대한민국법원 | 절차 선택 기준·오선택 위험·비교 또는 상담 경로가 공통으로 필요함 | Layer 2 CASE 60 승격 | 사례 카드, 3장 core-info, 4장 safety-net, 7장 컴포넌트, 부록 D, 코퍼스·테스트 |');
    expect(markdown).toContain('한 행에 대표 사이트 근거가 2곳 이상 모이지 않으면 Layer 2 후보로 올리지 않습니다. 먼저 Layer 3 로그로 남기고, 다음 순회에서 같은 실패가 다른 기관에서도 반복되는지 확인합니다.');
